insert into public.app_content (type, key, title, body, meta, sort_order) values
  ('class_topic', 'NumbersAndOperations', 'Counting & Cardinality', 'Understanding how to count objects, recognize that the last number in a count names the quantity, and use place-value concepts (e.g., ones, tens, hundreds) to represent and compare numbers.', '{"grade":"K-2","color":"#FF6B6B","help":{"videos":[{"title":"Counting","url":"https://youtu.be/mKSNQuQrsm0?feature=shared"},{"title":"Cardinal counting principle","url":"https://youtu.be/ieRYzlFWWUg?feature=shared"},{"title":"Counting and cardinality","url":"https://youtu.be/aSDi_PN2YoA?feature=shared"},{"title":"Place Value Song For Kids | Ones, Tens, & Hundreds","url":"https://youtu.be/a4FXl4zb3E4?feature=shared"},{"title":"Place Value","url":"https://youtu.be/T5Qf0qSSJFI?feature=shared"}]},"topic_key":"counting"}'::jsonb, 0),
  ('class_topic', 'NumbersAndOperations', 'Whole Number Operations', 'Mastery of addition, subtraction, multiplication, and division with nonnegative integers, including strategies (e.g., regrouping, arrays) and properties (commutative, associative).', '{"grade":"3-5","color":"#4D96FF","help":{"videos":[{"title":"Multiplying whole numbers","url":"https://youtu.be/SuC_ufEOHQc?feature=shared"},{"title":"Dividing whole numbers","url":"https://youtu.be/oNxjGOxTaOc?feature=shared"},{"title":"Adding whole numbers","url":"https://youtu.be/-MiH40ZUwq4?feature=shared"},{"title":"Subtracting whole numbers","url":"https://youtu.be/gIHYlZcr_1Y?feature=shared"},{"title":"Regrouping whole number place values","url":"https://youtu.be/i7lqWXKuhhQ?feature=shared"},{"title":"Multiplication with Arrays","url":"https://youtu.be/QphXFi30aFk?feature=shared"},{"title":"Multiplication Properties | Commutative, Associative, Identity, & Zero","url":"https://youtu.be/Doqt7bb8Gno?feature=shared"}]},"topic_key":"whole"}'::jsonb, 1),
  ('class_topic', 'NumbersAndOperations', 'Fractions & Decimals', 'Representing parts of a whole or group, comparing and ordering fractional and decimal values, and performing operations (addition, subtraction, multiplication, division) on them.', '{"grade":"6-8","color":"#4CAF50","help":{"videos":[{"title":"Comparing and Ordering Fractions, Decimals, and Percents","url":"https://youtu.be/5vv--qrUJXo?feature=shared"},{"title":"Converting Fractions to Decimals Song","url":"https://youtu.be/WV5VY76Pf5U?feature=shared"},{"title":"Compare & Order Fractions by Equivalency","url":"https://youtu.be/bj5fSn96Cns?feature=shared"},{"title":"Comparing Decimal Numbers","url":"https://youtu.be/rALUd3wW29s?feature=shared"},{"title":"Adding and Subtracting Fractions","url":"https://youtu.be/5juto2ze8Lg?feature=shared"},{"title":"Multiplication and Division of Fractions","url":"https://youtu.be/Q9MCRjrrd6E?feature=shared"},{"title":"Adding & Subtracting Decimals Song","url":"https://youtu.be/n-OcbG1FlBQ?feature=shared"},{"title":"How to Multiply Decimals and Divide Decimals","url":"https://youtu.be/jtstmHefBW8?feature=shared"}]},"topic_key":"fractions"}'::jsonb, 2),
  ('class_topic', 'NumbersAndOperations', 'Rational & Real Numbers', 'Extending number sense to include negatives, fractional and decimal numbers, and recognizing that both rational (e.g., ¾, –2) and irrational (e.g., √2, π) numbers fill out the number line.', '{"grade":"9-12","color":"#FFB74D","help":{"videos":[{"title":"Natural, Whole, Integers, Rational, Irrational, Real, Imaginary","url":"https://youtu.be/WxXZaP8Y8pI?feature=shared"},{"title":"An Intro to Rational and Irrational Numbers","url":"https://youtu.be/Th9mT4TxvOI?feature=shared"}]},"topic_key":"rational"}'::jsonb, 3),
  ('class_topic', 'AlgebraAndFunctions', 'Patterns & Relationships', 'Identifying and describing regularities in numbers or shapes, using tables, charts, or simple rules to predict what comes next.', '{"grade":"3-5","color":"#9C27B0","help":{"readings":[{"title":"Recognizing Patterns (LibreTexts)","url":"https://math.libretexts.org/Courses/Coalinga_College/Math_for_Educators_(MATH_010A_and_010B_CID120)/05%3A_Problem_Solving/5.06%3A_Recognizing_Patterns"}],"videos":[{"title":"Finding the Rule for the Pattern (using a table)","url":"https://youtu.be/OlUBFXfLE0c?feature=shared"}]},"topic_key":"patterns"}'::jsonb, 0),
  ('class_topic', 'AlgebraAndFunctions', 'Expressions & Equations', 'Writing and manipulating symbolic expressions (e.g., 3x + 5), solving equations and inequalities (linear, quadratic), and understanding equivalent forms.', '{"grade":"6-8","color":"#03A9F4","help":{"readings":[{"title":"Equivalent Expressions Guide","url":"https://thirdspacelearning.com/us/math-resources/topic-guides/algebra/equivalent-expressions/"}],"videos":[{"title":"Writing Algebraic Expressions","url":"https://youtu.be/o_Ubm7OI8t4?feature=shared"},{"title":"How To Solve Linear Inequalities (Basic Introduction)","url":"https://youtu.be/DrZJKdXlZ3I?feature=shared"},{"title":"Quadratic Equation Explained Step-by-Step","url":"https://youtu.be/gagj6GHZqnE?feature=shared"},{"title":"The Quadratic Formula Song","url":"https://youtu.be/VOXYMRcWbF8?feature=shared"},{"title":"How To Solve Quadratic Equations Using The Quadratic Formula","url":"https://youtu.be/IlNAJl36-10?feature=shared"}]},"topic_key":"expressions"}'::jsonb, 1),
  ('class_topic', 'AlgebraAndFunctions', 'Functions & Modeling', 'Interpreting and using the idea of a function—an input–output relationship—to model real-world situations with linear, quadratic, exponential, or other function types.', '{"grade":"9-12","color":"#FF9800","help":{"readings":[],"videos":[{"title":"Input-Output Relationships (basic)","url":"https://youtu.be/XAJ8LdOLmlk?feature=shared"}]},"topic_key":"functions"}'::jsonb, 2),
  ('class_topic', 'GeometrySpatialReasoning', 'Plane Geometry', 'Studying properties and relationships of flat shapes (points, lines, angles, triangles, polygons, and circles), including congruence and similarity.', '{"grade":"3-5","color":"#009688","help":{"readings":[{"title":"Plane geometry (Math is Fun)","url":"https://www.mathsisfun.com/geometry/plane-geometry.html"}],"videos":[]},"topic_key":"plane"}'::jsonb, 0),
  ('class_topic', 'GeometrySpatialReasoning', 'Coordinate Geometry', 'Placing and analyzing geometric figures in the plane using an (x,y) coordinate system; applying distance, midpoint, and slope formulas.', '{"grade":"6-8","color":"#3F51B5","help":{"readings":[{"title":"Introduction to coordinate geometry (BYJU''s)","url":"https://byjus.com/maths/coordinate-geometry/"}],"videos":[]},"topic_key":"coordinate"}'::jsonb, 1),
  ('class_topic', 'GeometrySpatialReasoning', 'Transformations & Symmetry', 'Exploring how shapes change under translations, rotations, reflections, and dilations, and understanding lines of symmetry.', '{"grade":"6-8","color":"#E91E63","help":{"readings":[{"title":"Symmetry in geometry (MathBitsNotebook)","url":"https://mathbitsnotebook.com/Geometry/Transformations/TRSymmetry.html"}],"videos":[{"title":"Symmetry and Transformations (Simplifying Math)","url":"https://youtu.be/XH8nSD4g0hg?feature=shared"}]},"topic_key":"transformations"}'::jsonb, 2),
  ('class_topic', 'GeometrySpatialReasoning', 'Solid Geometry', 'Examining three-dimensional figures (prisms, cylinders, pyramids, cones, spheres), focusing on their nets, surface areas, and volumes.', '{"grade":"9-12","color":"#FFC107","help":{"readings":[{"title":"Formulas for surface area and volume of 3D figures (ThoughtCo)","url":"https://www.thoughtco.com/surface-area-and-volume-2312247"}],"videos":[{"title":"Nets Of 3D Shapes Explained","url":"https://youtu.be/s7GrS0b3FRw?feature=shared"}]},"topic_key":"solid"}'::jsonb, 3),
  ('class_topic', 'Measurement', 'Units & Conversions', 'Selecting and converting among metric and customary units for length, weight/mass, volume/capacity, time, and temperature.', '{"grade":"K-2","color":"#2196F3","help":{"readings":[{"title":"Conversion Between the Metric and US Customary Systems of Measurement","url":"https://math.libretexts.org/Courses/Rio_Hondo/Math_150%3A_Survey_of_Mathematics/06%3A_Measurement_and_Geometry/6.01%3A_Measurement/6.1.03%3A_Conversion_Between_the_Metric_and_US_Customary_Systems_of_Measurement"},{"title":"Converting Temperatures (CK-12)","url":"https://flexbooks.ck12.org/cbook/ck-12-cbse-maths-class-6/section/6.10/primary/lesson/temperature-conversion/"}],"videos":[]},"topic_key":"units"}'::jsonb, 0),
  ('class_topic', 'Measurement', 'Perimeter, Area & Volume', 'Calculating lengths around shapes, sizes of surfaces, and capacities of solids using standard formulas.', '{"grade":"3-5","color":"#8BC34A","help":{"readings":[],"videos":[{"title":"Perimeter, Area, and Volume Explained","url":"https://youtu.be/2UEUWC313QY?feature=shared"}]},"topic_key":"perimeter"}'::jsonb, 1),
  ('class_topic', 'Measurement', 'Angle Measurement', 'Measuring and classifying angles (acute, right, obtuse), and applying protractors and angle-sum properties in polygons.', '{"grade":"6-8","color":"#FF5722","help":{"readings":[{"title":"How to determine acute; right; obtuse (Math is Fun)","url":"https://www.mathsisfun.com/angles.html"},{"title":"Sum of Angles in a Polygon (Cuemath)","url":"https://www.cuemath.com/geometry/sum-of-angles-in-a-polygon/"}],"videos":[{"title":"How To Use A Protractor To Measure And Draw Angles Explained From The Right And Left Side","url":"https://youtu.be/CHJ7_q4cCuE?feature=shared"},{"title":"ANGLE THEOREMS","url":"https://youtu.be/Bq1QyT-HZrU?feature=shared"},{"title":"How To Calculate The Interior Angles and Exterior Angles of a Regular Polygon","url":"https://youtu.be/OEzEo4XqzJQ?feature=shared"}]},"topic_key":"angles"}'::jsonb, 2),
  ('class_topic', 'Measurement', 'Applications', 'Applying measurement skills to real-life contexts such as reading maps (scale), cooking (units), and scheduling (time).', '{"grade":"9-12","color":"#FFEB3B","help":{"readings":[],"videos":[]},"topic_key":"applications"}'::jsonb, 3),
  ('class_topic', 'DataStatisticsProbability', 'Data Collection & Representation', 'Gathering data through surveys or experiments and displaying it in tables, bar graphs, line plots, histograms, or box plots.', '{"grade":"3-5","color":"#9C27B0","help":{"readings":[],"videos":[{"title":"Science of Data Visualization | Bar, scatter plot, line, histograms, pie, box plots, bubble chart","url":"https://youtu.be/csXmVBw8cdo?feature=shared"}]},"topic_key":"collection"}'::jsonb, 0),
  ('class_topic', 'DataStatisticsProbability', 'Descriptive Statistics', 'Summarizing data sets using measures of central tendency (mean, median, mode) and spread (range, interquartile range, standard deviation).', '{"grade":"6-8","color":"#E91E63","help":{"readings":[{"title":"Interquartile Range vs. Standard Deviation: What’s the Difference?","url":"https://www.statology.org/interquartile-range-vs-standard-deviation/"}],"videos":[{"title":"Mean, Median, Mode, and Range - How To Find It!","url":"https://youtu.be/A1mQ9kD-i9I?feature=shared"},{"title":"Standard Deviation, Variance, Range and Interquartile Range - Measures of dispersion","url":"https://youtu.be/WnMXXWWlylo?feature=shared"}]},"topic_key":"descriptive"}'::jsonb, 1),
  ('class_topic', 'DataStatisticsProbability', 'Probability', 'Calculating the likelihood of simple and compound events, using basic counting methods (permutations, combinations), and understanding theoretical vs. experimental probability.', '{"grade":"6-8","color":"#03A9F4","help":{"readings":[],"videos":[{"title":"Basic Probability","url":"https://youtu.be/KzfWUEJjG18?si=Q-XZEX9GvoLzpxJ6"}]},"topic_key":"probability"}'::jsonb, 2),
  ('class_topic', 'DataStatisticsProbability', 'Statistical Inference', '(High school) Designing samples, making estimates (confidence intervals), and testing hypotheses to draw conclusions about populations from data.', '{"grade":"9-12","color":"#4CAF50","help":{"readings":[],"videos":[{"title":"Understanding Statistical Inference","url":"https://youtu.be/tFRXsngz4UQ?si=vQEOTf5SdXlM9jtS"}]},"topic_key":"inference"}'::jsonb, 3),
  ('class_topic', 'AdvancedMath', 'Trigonometry', 'Defining sine, cosine, and tangent ratios in right and non-right triangles; exploring unit-circle definitions, graph behavior, and identities.', '{"grade":"9-12","color":"#673AB7","help":{"readings":[{"title":"Sine; Cosine; Tangent (Math is Fun)","url":"https://www.mathsisfun.com/sine-cosine-tangent.html"}],"videos":[{"title":"Intro to Trigonometry - sine, cosine, and tangent ratios","url":"https://youtu.be/Q9mjsjOenQQ?si=koZN_KFMj-8p77ck"},{"title":"Non Right angled Trigonometry, the Sine and Cosine rules","url":"https://youtu.be/5iYQCdL-bz4?si=_DrZADRqE-YeZgLa"},{"title":"The Unit Circle, Basic Introduction, Trigonometry","url":"https://youtu.be/57VrEiEPD1I?si=8M13tnSCCSfQ9Nhnaa"}]},"topic_key":"trigonometry"}'::jsonb, 0),
  ('class_topic', 'AdvancedMath', 'Precalculus', 'Delving into complex numbers, vectors, parametric and polar equations, advanced function families, and sequence/series fundamentals.', '{"grade":"9-12","color":"#00BCD4","help":{"readings":[{"title":"Intro to complex numbers (Khan Academy)","url":"https://www.khanacademy.org/math/algebra2/x2ec2f6f830c9fb89:complex/x2ec2f6f830c9fb89:complex-num/a/intro-to-complex-numbers"},{"title":"Vectors (BYJU''s)","url":"https://byjus.com/maths/vectors/"},{"title":"Sequence and Series (BYJU''s)","url":"https://byjus.com/maths/sequence-and-series/"}],"videos":[{"title":"Parametric Equations Introduction, Eliminating The Parameter t, Graphing Plane Curves, Precalculus","url":"https://youtu.be/97pe-QlSGqA?si=JIYJlufBcOZbLSqf"},{"title":"Function Families","url":"https://youtu.be/JzaeBxmvHl8?si=hiH5OcZFKKEGWqZB"}]},"topic_key":"precalculus"}'::jsonb, 1),
  ('class_topic', 'AdvancedMath', 'Calculus', 'Introducing limits and continuity, computing derivatives and integrals, and applying them to rate-of-change and area-under-curve problems.', '{"grade":"9-12","color":"#FF9800","help":{"readings":[{"title":"Derivatives and Integrals (BYJU''s)","url":"https://byjus.com/maths/calculus/"}],"videos":[{"title":"Limits and Continuity","url":"https://youtu.be/9brk313DjV8?si=AhPWiFxsra9naUJ-"},{"title":"Derivatives and Rate of Change","url":"https://youtu.be/xLE4C7y5Pn4?si=Q13q7N70Bl__c3p5"},{"title":"Finding The Area Under The Curve Using Definite Integrals","url":"https://youtu.be/UjTTx2eYrx8?si=Y8zqAQAH5E3dBf8s"}]},"topic_key":"calculus"}'::jsonb, 2),
  ('class_topic', 'AdvancedMath', 'Discrete Mathematics', '(Elective) Investigating logic and set theory, graph theory basics, recursion, and combinatorial reasoning for algorithmic thinking.', '{"grade":"9-12","color":"#8BC34A","help":{"readings":[{"title":"Graph Theory (DataCamp)","url":"https://www.datacamp.com/tutorial/introduction-to-graph-theory"}],"videos":[{"title":"Logic and Set Theory","url":"https://youtu.be/dH4RHHsTf6Q?si=YBf1_L4W-s3Ul7l6"},{"title":"Recursive Formulas For Sequences","url":"https://youtu.be/IFHZQ6MaG6w?si=SoCKhh_iesFq6uBW"}]},"topic_key":"discrete"}'::jsonb, 3),
  ('class_topic', 'Reading', 'Print Concepts', 'Understanding how books and print work (e.g., reading left to right, top to bottom, how to turn pages, recognizing that words are made of letters).', '{"grade":"K-2","color":"#8E24AA","help":{"videos":[{"title":"Concepts of Print for Kindergarten","url":"https://youtu.be/T-ybpyBWH2o?si=thyBAb1NXK87i7nd"}]},"topic_key":"printConcepts"}'::jsonb, 0),
  ('class_topic', 'Reading', 'Phonological Awareness', 'The ability to hear and manipulate sounds in spoken language. Includes skills like rhyming; syllable segmentation; blending and segmenting onset-rime; phonemic awareness (individual sounds in words).', '{"grade":"K-2","color":"#8E24AA","help":{"videos":[{"title":"Rhyming Words","url":"https://youtu.be/4PW3_LErVZk?si=HKt6zrULKIhfbIOA"},{"title":"Open and Closed Syllables","url":"https://youtu.be/epk-hnVC10k?si=7nGZ5YvC4TBofqnM"},{"title":"What are Syllables","url":"https://youtu.be/Um7ukvphdHY?si=OdpfjT59aEyajM-J"}]},"topic_key":"phonologicalAwareness"}'::jsonb, 1),
  ('class_topic', 'Reading', 'Phonics & Word Recognition', 'Phonics – Connecting sounds to letters (letter-sound correspondence). Helps children decode (sound out) words when reading. Word Recognition – The ability to recognize words quickly and effortlessly. Includes sight word recognition and decoding strategies.', '{"grade":"K-2","color":"#8E24AA","help":{"videos":[{"title":"Phonics Song","url":"https://youtu.be/BELlZKpi1Zs?si=LeLmN4KaNvK3aodr"},{"title":"Letter Sound - Phonics for Kids","url":"https://youtu.be/jiEv6VTDt5c?si=dEEEGVLSftui5YBL"},{"title":"Word recognition/site words","url":"https://youtu.be/gIZjrcG9pW0?si=HPzkNjgF1dAUD13S"}]},"topic_key":"phonicsWordRecognition"}'::jsonb, 2),
  ('class_topic', 'Reading', 'Fluency', 'Reading with speed, accuracy, and proper expression. Fluency bridges the gap between word recognition and comprehension.', '{"grade":"K-2","color":"#8E24AA","help":{"videos":[{"title":"Reading Fluency: Speed, Accuracy, and Expression","url":"https://youtu.be/i0cQu7vnDzs?si=NiK07cZVwQHYNSlw"}]},"topic_key":"fluency"}'::jsonb, 3),
  ('class_topic', 'Reading', 'Story Elements', 'Story Elements (plot, character, setting).', '{"grade":"3-5","color":"#039BE5","help":{"videos":[{"title":"Story Elements Song | Character, Setting and Plot!","url":"https://youtu.be/m3WHmmYTHeE?si=ma9elO11dO6LwOPM"}]},"topic_key":"storyElements"}'::jsonb, 4),
  ('class_topic', 'Reading', 'Themes & Author’s Purpose', 'Themes & Author’s Purpose.', '{"grade":"3-5","color":"#039BE5","help":{"videos":[{"title":"Theme","url":"https://youtu.be/xwkKBIzpRXE?si=T5etTG1nn67v3Mdc"},{"title":"Author''s Purpose","url":"https://youtu.be/enm4afX-izA?si=k48sPixqvR9AU8Xw"}]},"topic_key":"themesAuthorsPurpose"}'::jsonb, 5),
  ('class_topic', 'Reading', 'Literary Devices', 'Literary Devices (metaphor, symbolism, etc.).', '{"grade":"6-8","color":"#039BE5","help":{"videos":[{"title":"Literary Devices (Onomatopoeia, Personification, Simile, and Metaphor)","url":"https://youtu.be/JaYPoeMJECg?si=R30S0NpJ-LbNMkAv"}]},"topic_key":"literaryDevices"}'::jsonb, 6),
  ('class_topic', 'Reading', 'Main Idea & Supporting Details', 'Main Idea & Supporting Details.', '{"grade":"3-5","color":"#FB8C00","help":{"videos":[{"title":"Main Idea and Supporting Details","url":"https://youtu.be/LWFnpeimPfE?si=t6Wxkg-3-Zd_VrUB"}]},"topic_key":"mainIdea"}'::jsonb, 7),
  ('class_topic', 'Reading', 'Text Features', 'Text Features (headings, charts, captions).', '{"grade":"3-5","color":"#FB8C00","help":{"videos":[{"title":"Nonfiction Text Features","url":"https://youtu.be/GQ03w1Igolc?si=4NluGSeDvhgmV9s4"}]},"topic_key":"textFeatures"}'::jsonb, 8),
  ('class_topic', 'Reading', 'Text Structure', 'Text Structure (cause/effect, compare/contrast, sequence).', '{"grade":"6-8","color":"#FB8C00","help":{"videos":[{"title":"The 5 Types of Text Structure | Educational Rap","url":"https://youtu.be/7kWGQ-_ipBY?si=pgAj0eo48YkWOOSU"}]},"topic_key":"textStructure"}'::jsonb, 9),
  ('class_topic', 'Reading', 'Context Clues', 'Context Clues.', '{"grade":"3-5","color":"#43A047","help":{"videos":[{"title":"Context Clues","url":"https://youtu.be/eHCpJ86XDY4?si=sSEmA05h27xCQS5u"}]},"topic_key":"contextClues"}'::jsonb, 10),
  ('class_topic', 'Reading', 'Word Roots & Affixes', 'Word Roots & Affixes.', '{"grade":"6-8","color":"#43A047","help":{"videos":[{"title":"Root Word and Affixes","url":"https://youtu.be/H2NZuH8dUW0?si=7YcrghiLkwGmCuog"}]},"topic_key":"wordRootsAffixes"}'::jsonb, 11),
  ('class_topic', 'Reading', 'Academic & Domain-Specific Terms', 'Academic & Domain-Specific Terms.', '{"grade":"9-12","color":"#43A047","help":{"videos":[{"title":"Academic and Domain-Specific Words, Context Clues","url":"https://youtu.be/1LZH7iEvqFg?si=S9TpqgEhkLWCZH5E"}]},"topic_key":"academicDomainTerms"}'::jsonb, 12),
  ('class_topic', 'Reading', 'Making Inferences', 'Making Inferences.', '{"grade":"6-8","color":"#D32F2F","help":{"videos":[{"title":"Inferences | Making Inferences","url":"https://youtu.be/JdaD2FZQFEY?si=uXXvzgOD7KQs1OBU"}]},"topic_key":"makingInferences"}'::jsonb, 13),
  ('class_topic', 'Reading', 'Summarizing', 'Summarizing.', '{"grade":"3-5","color":"#D32F2F","help":{"videos":[{"title":"Summarizing a Story","url":"https://youtu.be/4jUi0pSQ-bU?si=fcP2L_2o8fG-ky1O"}]},"topic_key":"summarizing"}'::jsonb, 14),
  ('class_topic', 'Reading', 'Monitoring & Self-Questioning', 'Monitoring & Self-Questioning.', '{"grade":"9-12","color":"#D32F2F","help":{"videos":[{"title":"Self-Monitoring","url":"https://youtu.be/SK6tl16dKo0?si=OMWDt9AFFKt4g1Tp"}]},"topic_key":"monitoringSelfQuestioning"}'::jsonb, 15),
  ('class_topic', 'Writing', 'Opinion/Argumentative', 'Writing that expresses a clear viewpoint and supports it with reasons and evidence.', '{"grade":"6-8","color":"#8E24AA","help":{"videos":[{"title":"Text Types (Narrative, Informative, Argumentative)","url":"https://youtu.be/EKpFKe8eQ3U?si=Mv-JINsX6XlwcXzJ"}]},"topic_key":"opinionArgumentative"}'::jsonb, 0),
  ('class_topic', 'Writing', 'Informative/Explanatory', 'Writing that explains facts or concepts clearly to inform the reader.', '{"grade":"3-5","color":"#8E24AA","help":{"videos":[{"title":"Text Types (Narrative, Informative, Argumentative)","url":"https://youtu.be/EKpFKe8eQ3U?si=Mv-JINsX6XlwcXzJ"}]},"topic_key":"informativeExplanatory"}'::jsonb, 1),
  ('class_topic', 'Writing', 'Narrative', 'Writing that tells a story with characters, setting, and plot.', '{"grade":"K-2","color":"#8E24AA","help":{"videos":[{"title":"Text Types (Narrative, Informative, Argumentative)","url":"https://youtu.be/EKpFKe8eQ3U?si=Mv-JINsX6XlwcXzJ"}]},"topic_key":"narrative"}'::jsonb, 2),
  ('class_topic', 'Writing', 'Planning & Research', 'Gathering ideas and information before writing.', '{"grade":"3-5","color":"#039BE5","help":{"videos":[{"title":"The Writing Process: A Step by Step Guide to Academic Writing","url":"https://youtu.be/1JQxCNgr5MQ?si=67_xEW35jZ_Y4BhJ"}]},"topic_key":"planningResearch"}'::jsonb, 3),
  ('class_topic', 'Writing', 'Drafting', 'Putting ideas into a first draft to get the writing on paper.', '{"grade":"3-5","color":"#039BE5","help":{"videos":[{"title":"The Writing Process: A Step by Step Guide to Academic Writing","url":"https://youtu.be/1JQxCNgr5MQ?si=67_xEW35jZ_Y4BhJ"}]},"topic_key":"drafting"}'::jsonb, 4),
  ('class_topic', 'Writing', 'Revising & Editing', 'Improving and correcting the draft to make it clearer and error-free.', '{"grade":"6-8","color":"#039BE5","help":{"videos":[{"title":"The Writing Process: A Step by Step Guide to Academic Writing","url":"https://youtu.be/1JQxCNgr5MQ?si=67_xEW35jZ_Y4BhJ"}]},"topic_key":"revisingEditing"}'::jsonb, 5),
  ('class_topic', 'Writing', 'Publishing', 'Sharing the final version of writing with others.', '{"grade":"6-8","color":"#039BE5","help":{"videos":[{"title":"The Writing Process: A Step by Step Guide to Academic Writing","url":"https://youtu.be/1JQxCNgr5MQ?si=67_xEW35jZ_Y4BhJ"}]},"topic_key":"publishing"}'::jsonb, 6),
